import { StyleSheet } from 'react-native';

const styles = StyleSheet.create({   
    listText: {
        fontSize: 19,
        color: '#fff',
        backgroundColor: '#fff',
        padding: 5,
        margin: 5,
        borderRadius: 10,
    },

    load: {
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: 'rgba(0,0,0,0.0)',
        borderColor:'rgba(255,255,255,0.5)',
        borderWidth: 1.5,
        padding: 5,
        margin: 5,
        borderRadius: 10,
    },
});
export { styles };
